"""seqmodel: 从零实现的序列建模库（仅 Python 标准库，离线）。

包含一个确定性的 VanillaRNN（字符级）以及两个 CLI 子命令：

    python seqmodel.py train-rnn --data CORPUS --epochs N --hidden-size H \
        --seed S --model-out model.json [--tbptt-steps K] [--learning-rate LR]
    python seqmodel.py sample --model model.json --prompt TEXT \
        --length N --seed S --temperature T

相同输入与相同种子必须产生逐字节相同的输出。
"""

import argparse
import json
import math
import random
import sys

INIT_SCALE = 0.01
DEFAULT_CLIP_NORM = 5.0
DEFAULT_LEARNING_RATE = 0.1


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def _is_finite_number(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool) \
        and math.isfinite(value)


def _check_index_sequence(values, vocab_size, name):
    if not isinstance(values, (list, tuple)):
        raise ValueError("%s must be a list of integers" % name)
    result = []
    for v in values:
        if not _is_int(v):
            raise ValueError("%s entries must be integers, got %r" % (name, v))
        if v < 0 or v >= vocab_size:
            raise ValueError(
                "%s entry %d out of range [0, %d)" % (name, v, vocab_size))
        result.append(v)
    return result


def _check_vector(values, size, name):
    if not isinstance(values, (list, tuple)) or len(values) != size:
        raise ValueError("%s must be a vector of length %d" % (name, size))
    result = []
    for v in values:
        if not _is_finite_number(v):
            raise ValueError("%s entries must be finite numbers, got %r"
                             % (name, v))
        result.append(float(v))
    return result


def _zeros_like_params(params):
    zeros = {}
    for key, value in params.items():
        if isinstance(value, list) and value and isinstance(value[0], list):
            zeros[key] = [[0.0] * len(row) for row in value]
        else:
            zeros[key] = [0.0] * len(value)
    return zeros


class VanillaRNN(object):
    """确定性 Vanilla RNN：h = tanh(Wxh x + Whh h + bh), y = Why h + by。"""

    PARAM_SHAPES = ("Wxh", "Whh", "Why", "bh", "by")

    def __init__(self, vocab_size, hidden_size, seed):
        if not _is_int(vocab_size) or vocab_size <= 0:
            raise ValueError("vocab_size must be a positive integer")
        if not _is_int(hidden_size) or hidden_size <= 0:
            raise ValueError("hidden_size must be a positive integer")
        if not _is_int(seed):
            raise ValueError("seed must be an integer")
        self.vocab_size = vocab_size
        self.hidden_size = hidden_size
        self.seed = seed

        rng = random.Random(seed)

        def rand_matrix(rows, cols):
            return [[rng.gauss(0.0, 1.0) * INIT_SCALE for _ in range(cols)]
                    for _ in range(rows)]

        self.params = {
            "Wxh": rand_matrix(hidden_size, vocab_size),
            "Whh": rand_matrix(hidden_size, hidden_size),
            "Why": rand_matrix(vocab_size, hidden_size),
            "bh": [0.0] * hidden_size,
            "by": [0.0] * vocab_size,
        }

    # ------------------------------------------------------------------
    # 前向传播
    # ------------------------------------------------------------------
    def forward(self, sequence, targets=None, h0=None):
        """前向传播，返回 (logits, loss, cache)。

        sequence: 整数索引列表；targets: 等长整数索引或 None；
        h0: 初始隐状态，默认全零。空序列返回 ([], 0.0, cache)。
        """
        sequence = _check_index_sequence(sequence, self.vocab_size, "sequence")
        if h0 is None:
            h_prev = [0.0] * self.hidden_size
        else:
            h_prev = _check_vector(h0, self.hidden_size, "h0")
        if targets is not None:
            targets = _check_index_sequence(targets, self.vocab_size, "targets")
            if len(targets) != len(sequence):
                raise ValueError("targets must have the same length as sequence")

        Wxh = self.params["Wxh"]
        Whh = self.params["Whh"]
        Why = self.params["Why"]
        bh = self.params["bh"]
        by = self.params["by"]

        hs = [list(h_prev)]  # hs[t] 为第 t 步之前的隐状态
        logits_list = []
        probs_list = []
        loss = 0.0

        for t, x in enumerate(sequence):
            h = [0.0] * self.hidden_size
            for i in range(self.hidden_size):
                acc = Wxh[i][x] + bh[i]
                row = Whh[i]
                for j in range(self.hidden_size):
                    acc += row[j] * h_prev[j]
                h[i] = math.tanh(acc)
            y = [0.0] * self.vocab_size
            for v in range(self.vocab_size):
                acc = by[v]
                row = Why[v]
                for j in range(self.hidden_size):
                    acc += row[j] * h[j]
                y[v] = acc
                if not math.isfinite(acc):
                    raise ValueError("non-finite logit encountered in forward")
            p = _softmax(y)
            logits_list.append(y)
            probs_list.append(p)
            hs.append(h)
            if targets is not None:
                loss -= math.log(p[targets[t]])
            h_prev = h

        if targets is not None and len(sequence) > 0:
            loss /= len(sequence)
            if not math.isfinite(loss):
                raise ValueError("non-finite loss encountered in forward")

        cache = {
            "sequence": list(sequence),
            "targets": list(targets) if targets is not None else None,
            "h0": list(hs[0]),
            "hs": hs,
            "logits": logits_list,
            "probs": probs_list,
        }
        return logits_list, loss, cache

    # ------------------------------------------------------------------
    # 反向传播（支持 TBPTT）
    # ------------------------------------------------------------------
    def backward(self, sequence, targets, cache, tbptt_steps=None):
        """反向传播，返回 (grads, dh0)。

        tbptt_steps 为 None 时做完整 BPTT；为正整数时隐状态前向仍连续，
        但每一步的梯度最多向前回传该窗口长度。
        """
        sequence = _check_index_sequence(sequence, self.vocab_size, "sequence")
        targets = _check_index_sequence(targets, self.vocab_size, "targets")
        if len(targets) != len(sequence):
            raise ValueError("targets must have the same length as sequence")
        if tbptt_steps is not None:
            if not _is_int(tbptt_steps) or tbptt_steps <= 0:
                raise ValueError("tbptt_steps must be a positive integer or None")
        if not isinstance(cache, dict) or "hs" not in cache or "probs" not in cache:
            raise ValueError("cache must come from forward()")
        hs = cache["hs"]
        probs = cache["probs"]
        if len(hs) != len(sequence) + 1 or len(probs) != len(sequence):
            raise ValueError("cache is inconsistent with sequence length")

        grads = _zeros_like_params(self.params)
        dh0 = [0.0] * self.hidden_size
        T = len(sequence)
        if T == 0:
            return grads, dh0

        Wxh = self.params["Wxh"]
        Whh = self.params["Whh"]
        Why = self.params["Why"]

        window = T if tbptt_steps is None else min(tbptt_steps, T)
        inv_T = 1.0 / T

        # 从序列末端按 window 分块，块内做完整 BPTT，块间梯度不传递。
        block_end = T
        while block_end > 0:
            block_start = max(0, block_end - window)
            dh_next = [0.0] * self.hidden_size
            for t in range(block_end - 1, block_start - 1, -1):
                h_next = hs[t + 1]
                h_prev = hs[t]
                dy = list(probs[t])
                dy[targets[t]] -= 1.0
                for v in range(self.vocab_size):
                    dy[v] *= inv_T
                gWhy = grads["Why"]
                gby = grads["by"]
                for v in range(self.vocab_size):
                    dv = dy[v]
                    gby[v] += dv
                    row = gWhy[v]
                    for j in range(self.hidden_size):
                        row[j] += dv * h_next[j]
                dh = list(dh_next)
                for j in range(self.hidden_size):
                    acc = dh[j]
                    for v in range(self.vocab_size):
                        acc += Why[v][j] * dy[v]
                    dh[j] = acc
                dtanh = [dh[i] * (1.0 - h_next[i] * h_next[i])
                         for i in range(self.hidden_size)]
                gbh = grads["bh"]
                gWxh = grads["Wxh"]
                gWhh = grads["Whh"]
                x = sequence[t]
                for i in range(self.hidden_size):
                    di = dtanh[i]
                    gbh[i] += di
                    gWxh[i][x] += di
                    row = gWhh[i]
                    for j in range(self.hidden_size):
                        row[j] += di * h_prev[j]
                dh_next = [0.0] * self.hidden_size
                for j in range(self.hidden_size):
                    acc = 0.0
                    for i in range(self.hidden_size):
                        acc += Whh[i][j] * dtanh[i]
                    dh_next[j] = acc
            if block_start == 0:
                dh0 = dh_next
            block_end = block_start

        return grads, dh0

    # ------------------------------------------------------------------
    # 梯度裁剪与参数更新
    # ------------------------------------------------------------------
    def _check_grads(self, grads):
        if not isinstance(grads, dict):
            raise ValueError("grads must be a dict keyed by parameter name")
        for key in self.PARAM_SHAPES:
            if key not in grads:
                raise ValueError("grads is missing key %r" % key)
            expected = self.params[key]
            got = grads[key]
            if isinstance(expected[0], list):
                if (not isinstance(got, (list, tuple)) or len(got) != len(expected)
                        or any(not isinstance(row, (list, tuple))
                               or len(row) != len(expected[0]) for row in got)):
                    raise ValueError("grads[%r] has wrong shape" % key)
                for row in got:
                    for v in row:
                        if not _is_finite_number(v):
                            raise ValueError("grads[%r] has non-finite values" % key)
            else:
                if not isinstance(got, (list, tuple)) or len(got) != len(expected):
                    raise ValueError("grads[%r] has wrong shape" % key)
                for v in got:
                    if not _is_finite_number(v):
                        raise ValueError("grads[%r] has non-finite values" % key)

    def clip_gradients(self, grads, max_norm):
        """按全局 L2 范数等比裁剪，不修改输入。

        返回 (clipped, before, after)：裁剪后的新梯度字典、裁剪前范数、
        裁剪后范数。
        """
        if not _is_finite_number(max_norm) or max_norm <= 0:
            raise ValueError("max_norm must be a positive finite number")
        self._check_grads(grads)
        total = 0.0
        for key in self.PARAM_SHAPES:
            value = grads[key]
            if isinstance(value[0], list):
                for row in value:
                    for v in row:
                        total += v * v
            else:
                for v in value:
                    total += v * v
        before = math.sqrt(total)
        scale = min(1.0, max_norm / before) if before > 0 else 1.0
        clipped = {}
        for key in self.PARAM_SHAPES:
            value = grads[key]
            if isinstance(value[0], list):
                clipped[key] = [[v * scale for v in row] for row in value]
            else:
                clipped[key] = [v * scale for v in value]
        after = before * scale
        return clipped, before, after

    def sgd_step(self, grads, lr):
        """校验梯度形状与有限 lr 后原地更新参数。"""
        if not _is_finite_number(lr):
            raise ValueError("lr must be a finite number")
        self._check_grads(grads)
        for key in self.PARAM_SHAPES:
            param = self.params[key]
            grad = grads[key]
            if isinstance(param[0], list):
                for i in range(len(param)):
                    prow = param[i]
                    grow = grad[i]
                    for j in range(len(prow)):
                        prow[j] -= lr * grow[j]
            else:
                for i in range(len(param)):
                    param[i] -= lr * grad[i]


def _softmax(logits):
    m = max(logits)
    exps = [math.exp(z - m) for z in logits]
    s = sum(exps)
    return [e / s for e in exps]


# ----------------------------------------------------------------------
# CLI: train-rnn
# ----------------------------------------------------------------------
def _cmd_train_rnn(args):
    with open(args.data, "r", encoding="utf-8") as f:
        corpus = f.read()
    if len(corpus) == 0:
        raise ValueError("corpus is empty: %s" % args.data)
    if args.epochs < 0:
        raise ValueError("epochs must be non-negative")
    if args.tbptt_steps is not None and args.tbptt_steps <= 0:
        raise ValueError("tbptt-steps must be a positive integer")

    vocab = sorted(set(corpus))
    char_to_ix = {c: i for i, c in enumerate(vocab)}
    data = [char_to_ix[c] for c in corpus]
    sequence = data[:-1]
    targets = data[1:]

    model = VanillaRNN(len(vocab), args.hidden_size, args.seed)
    losses = []
    for _ in range(args.epochs):
        _, loss, cache = model.forward(sequence, targets)
        grads, _ = model.backward(sequence, targets, cache,
                                  tbptt_steps=args.tbptt_steps)
        clipped, _, _ = model.clip_gradients(grads, DEFAULT_CLIP_NORM)
        model.sgd_step(clipped, args.learning_rate)
        losses.append(loss)

    payload = {
        "losses": losses,
        "vocab": vocab,
        "parameters": model.params,
        "tbptt_steps": args.tbptt_steps,
    }
    with open(args.model_out, "w", encoding="utf-8") as f:
        f.write(json.dumps(payload, indent=2, sort_keys=True))
        f.write("\n")
    return 0


# ----------------------------------------------------------------------
# CLI: sample
# ----------------------------------------------------------------------
def _cmd_sample(args):
    with open(args.model, "r", encoding="utf-8") as f:
        payload = json.load(f)
    for key in ("vocab", "parameters"):
        if key not in payload:
            raise ValueError("model file is missing key %r" % key)
    vocab = payload["vocab"]
    params = payload["parameters"]
    if not vocab:
        raise ValueError("model vocab is empty")
    char_to_ix = {c: i for i, c in enumerate(vocab)}

    hidden_size = len(params["bh"])
    model = VanillaRNN(len(vocab), hidden_size, 0)
    for key in VanillaRNN.PARAM_SHAPES:
        if key not in params:
            raise ValueError("model file is missing parameter %r" % key)
    # 借用校验逻辑确认形状与有限性，然后整体替换参数。
    model._check_grads(params)
    model.params = {key: ([[float(v) for v in row] for row in params[key]]
                          if isinstance(params[key][0], list)
                          else [float(v) for v in params[key]])
                    for key in VanillaRNN.PARAM_SHAPES}

    if args.length < 0:
        raise ValueError("length must be non-negative")
    if not math.isfinite(args.temperature) or args.temperature < 0:
        raise ValueError("temperature must be a non-negative finite number")
    if len(args.prompt) == 0:
        raise ValueError("prompt must not be empty")
    for ch in args.prompt:
        if ch not in char_to_ix:
            raise ValueError("prompt contains unknown character %r" % ch)

    rng = random.Random(args.seed)
    h = [0.0] * hidden_size
    last_logits = None
    for ch in args.prompt:
        logits, _, cache = model.forward([char_to_ix[ch]], h0=h)
        h = cache["hs"][-1]
        last_logits = logits[0]

    out = []
    for _ in range(args.length):
        if args.temperature == 0:
            nxt = max(range(len(vocab)), key=lambda i: (last_logits[i], -i))
        else:
            probs = _softmax([z / args.temperature for z in last_logits])
            r = rng.random()
            cumulative = 0.0
            nxt = len(vocab) - 1
            for i, p in enumerate(probs):
                cumulative += p
                if r < cumulative:
                    nxt = i
                    break
        out.append(vocab[nxt])
        logits, _, cache = model.forward([nxt], h0=h)
        h = cache["hs"][-1]
        last_logits = logits[0]

    sys.stdout.write(args.prompt + "".join(out) + "\n")
    return 0


def _build_parser():
    parser = argparse.ArgumentParser(
        prog="seqmodel", description=__doc__.splitlines()[0])
    sub = parser.add_subparsers(dest="command", required=True)

    p_train = sub.add_parser("train-rnn", help="train a char-level RNN")
    p_train.add_argument("--data", required=True, help="corpus text file")
    p_train.add_argument("--epochs", type=int, default=10)
    p_train.add_argument("--hidden-size", type=int, default=32)
    p_train.add_argument("--seed", type=int, default=0)
    p_train.add_argument("--model-out", required=True, help="output model JSON")
    p_train.add_argument("--tbptt-steps", type=int, default=None)
    p_train.add_argument("--learning-rate", type=float,
                         default=DEFAULT_LEARNING_RATE)
    p_train.set_defaults(func=_cmd_train_rnn)

    p_sample = sub.add_parser("sample", help="sample text from a trained model")
    p_sample.add_argument("--model", required=True, help="model JSON file")
    p_sample.add_argument("--prompt", required=True)
    p_sample.add_argument("--length", type=int, default=100)
    p_sample.add_argument("--seed", type=int, default=0)
    p_sample.add_argument("--temperature", type=float, default=1.0)
    p_sample.set_defaults(func=_cmd_sample)
    return parser


def main(argv=None):
    parser = _build_parser()
    args = parser.parse_args(argv)
    try:
        return args.func(args)
    except ValueError as exc:
        print("error: %s" % exc, file=sys.stderr)
        return 1
    except OSError as exc:
        print("error: %s" % exc, file=sys.stderr)
        return 1


if __name__ == "__main__":
    sys.exit(main())

